namespace {
/// Convert a hardware prefix like "left_" to a ROS 2 namespace like "left".
std::string prefixToNamespace(const std::string& prefix) {
  if (prefix.empty()) {
    return "";
  }
  if (prefix.back() == '_') {
    return prefix.substr(0, prefix.size() - 1);
  }
  return prefix;
}
}  // namespace

